<div class="container-fluid py-3"><div class="d-flex justify-content-between align-items-center mb-3"><h4>Consultations et prêts physiques</h4><button type="button" class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#loanModal">Nouvelle demande</button></div>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-striped align-middle mb-0"><thead><tr><th>Numéro</th><th>Type</th><th>Emprunteur</th><th>Statut</th><th>Retour prévu</th><th>Actions</th></tr></thead><tbody><?php foreach($loans as $l):?><tr><td><strong><?=html_escape($l['number'])?></strong></td><td><?=html_escape($l['request_type'])?></td><td><?= (int)$l['borrower_user_id'] ?></td><td><?=html_escape($l['status'])?></td><td><?=html_escape($l['due_at'])?></td><td>
<?php if($l['status']==='demande'):?><form method="post" action="<?=site_url('loans/validate_request')?>" class="d-inline"><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><input type="hidden" name="loan_id" value="<?= (int)$l['id'] ?>"><button class="btn btn-sm btn-success">Valider</button></form><?php endif;?>
<?php if($l['status']==='valide'):?><form method="post" action="<?=site_url('loans/exit_loan')?>" class="d-inline"><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><input type="hidden" name="loan_id" value="<?= (int)$l['id'] ?>"><button class="btn btn-sm btn-warning">Sortie</button></form><?php endif;?>
<?php if(in_array($l['status'],['sorti','en_retard'],true)):?><form method="post" action="<?=site_url('loans/return_loan')?>" class="d-inline"><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><input type="hidden" name="loan_id" value="<?= (int)$l['id'] ?>"><input type="hidden" name="return_state" value="bon"><input type="hidden" name="reason" value="Retour standard"><button class="btn btn-sm btn-primary">Retour</button></form><?php endif;?>
</td></tr><?php endforeach;?></tbody></table></div></div>

<div class="modal fade" id="loanModal" tabindex="-1"><div class="modal-dialog"><form method="post" action="<?=site_url('loans/create_request')?>"><input type="hidden" name="<?=$this->security->get_csrf_token_name()?>" value="<?=$this->security->get_csrf_hash()?>"><div class="modal-content"><div class="modal-header"><h5>Nouvelle demande</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><label class="form-label">Unité physique</label><select name="physical_item_id" class="form-control" required><option value="">Sélectionner</option><?php foreach($items as $i):?><option value="<?= (int)$i['id'] ?>"><?=html_escape($i['reference'].' — boîte '.(int)$i['box_id'])?></option><?php endforeach;?></select><label class="form-label mt-2">Type</label><select name="request_type" class="form-control"><option value="consultation">Consultation sur place</option><option value="pret">Prêt physique</option></select><label class="form-label mt-2">Emprunteur interne</label><select name="borrower_user_id" class="form-control" required><?php foreach($users as $u):?><option value="<?= (int)$u['id'] ?>"><?=html_escape($u['lname'].' '.$u['fname'].' ('.$u['username'].')')?></option><?php endforeach;?></select><label class="form-label mt-2">Service</label><input type="text" name="service" class="form-control"><label class="form-label mt-2">Motif</label><textarea name="reason" class="form-control"></textarea></div><div class="modal-footer"><button type="submit" class="btn btn-primary">Créer</button></div></div></form></div></div>
